class PrintNumbers {

    void printNumbers(int n) {

        for (int i = 1; i <= n; i++) {
            System.out.print(i + " ");
        }
    }
}

import java.util.Scanner;

class NaturalNumber {

    int findSum(int n) {

        int sum = 0;

        for (int i = 1; i <= n; i++) {
            sum = sum + i;
        }

        return sum;
    }
}

class Main {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        NaturalNumber naturalNumber =
                new NaturalNumber();

        int result =
                naturalNumber.findSum(n);

        System.out.println(result);
    }
}

import java.util.Scanner;

class SquareSum {

    int findSquareSum(int n) {

        int sum = 0;

        for (int i = 1; i <= n; i++) {
            sum = sum + (i * i);
        }

        return sum;
    }
}

class Main {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        SquareSum squareSum =
                new SquareSum();

        int result =
                squareSum.findSquareSum(n);

        System.out.println(result);
    }
}

